-- All fixtures and outbound cleanup requests are rolled back.
begin;
do $$
declare
  a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid();
  g uuid; other_group uuid; r uuid:=gen_random_uuid(); other_r uuid:=gen_random_uuid(); comment_id uuid; invitation text;
  result jsonb; state jsonb; affected integer;
begin
  insert into auth.users(id,is_anonymous,raw_user_meta_data) values(a,false,'{}'),(b,false,'{}'),(c,false,'{}'),(d,false,'{}'),(outsider,false,'{}');
  perform set_config('request.jwt.claim.sub',a::text,true);
  perform set_config('role','authenticated',true);
  g:=public.create_catalog_group('투표 테스트','#5285bc');
  invitation:=public.create_catalog_invite(g);
  other_group:=public.create_catalog_group('다른 그룹 보존','#b87981');
  insert into public.restaurants(id,group_id,created_by,name,category,rating,area,lat,lng) values(r,g,a,'같은 식당','한식',2,'서울',37.5,127),(other_r,other_group,a,'같은 식당','한식',1,'서울',37.5,127);
  insert into public.restaurant_photos(restaurant_id,storage_path,created_by,sort_order) values(r,r::text||'/test.jpg',a,0);
  insert into storage.objects(bucket_id,name) values('restaurant-photos',r::text||'/test.jpg');
  state:=public.restaurant_discussion(r);
  if (state->>'eligible')::integer<>0 or (state->>'can_vote')::boolean then raise exception 'author counted as eligible'; end if;
  begin perform public.cast_restaurant_vote(r,1,'up'); raise exception 'author allowed to vote'; exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub',b::text,true); perform public.join_catalog_group(invitation);
  perform set_config('request.jwt.claim.sub',c::text,true); perform public.join_catalog_group(invitation);
  perform set_config('request.jwt.claim.sub',d::text,true); perform public.join_catalog_group(invitation);
  state:=public.restaurant_discussion(r);
  if (state->>'eligible')::integer<>3 or (state->>'required')::integer<>2 then raise exception 'wrong denominator'; end if;
  insert into public.restaurant_comments(restaurant_id,user_id,body) values(r,d,'내 의견') returning id into comment_id;
  update public.restaurant_comments set body='수정한 의견' where id=comment_id;
  if (select body from public.restaurant_comments where id=comment_id)<>'수정한 의견' then raise exception 'own comment update failed'; end if;
  begin update public.restaurant_comments set user_id=b where id=comment_id; raise exception 'comment reassignment allowed'; exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub',b::text,true);
  update public.restaurant_comments set body='다른 사람 수정' where id=comment_id; get diagnostics affected=row_count;
  if affected<>0 then raise exception 'nonowner comment update allowed'; end if;
  delete from public.restaurant_comments where id=comment_id; get diagnostics affected=row_count;
  if affected<>0 then raise exception 'nonowner comment delete allowed'; end if;
  begin insert into public.restaurant_comments(restaurant_id,user_id,body) values(r,b,' '); raise exception 'empty comment accepted'; exception when check_violation then null; end;
  begin insert into public.restaurant_votes(restaurant_id,round,user_id,choice) values(r,1,b,'up'); raise exception 'direct vote write allowed'; exception when insufficient_privilege then null; end;
  result:=public.cast_restaurant_vote(r,1,'up');
  if result->>'outcome'<>'pending' then raise exception 'one vote changed medal'; end if;
  perform public.cast_restaurant_vote(r,1,'up');
  if (select count(*) from public.restaurant_votes where restaurant_id=r)<>1 then raise exception 'duplicate vote counted twice'; end if;
  perform public.cast_restaurant_vote(r,1,'keep');
  perform set_config('request.jwt.claim.sub',c::text,true); perform public.cast_restaurant_vote(r,1,'keep');
  state:=public.restaurant_discussion(r);
  if (state->'votes'->>'keep')::integer<>2 or (state->>'round')::integer<>1 then raise exception 'keep changed medal or restarted round'; end if;
  perform set_config('request.jwt.claim.sub',b::text,true); perform public.cast_restaurant_vote(r,1,'up');
  perform set_config('request.jwt.claim.sub',c::text,true); result:=public.cast_restaurant_vote(r,1,'up');
  if result->>'outcome'<>'up' or (result->>'rating')::integer<>3 or (result->>'round')::integer<>2 then raise exception 'majority failed to raise medal once'; end if;
  if (select count(*) from public.restaurant_votes where restaurant_id=r)<>0 then raise exception 'old votes carried over'; end if;
  begin perform public.cast_restaurant_vote(r,1,'down'); raise exception 'stale round accepted'; exception when raise_exception then if sqlerrm<>'vote_round_changed' then raise; end if; end;
  begin perform public.cast_restaurant_vote(r,2,'up'); raise exception 'gold raised'; exception when raise_exception then if sqlerrm<>'already_gold' then raise; end if; end;
  perform public.cast_restaurant_vote(r,2,'down');
  perform set_config('request.jwt.claim.sub',b::text,true); result:=public.cast_restaurant_vote(r,2,'down');
  if (result->>'rating')::integer<>2 then raise exception 'gold did not fall to silver'; end if;
  perform public.cast_restaurant_vote(r,3,'down');
  perform set_config('request.jwt.claim.sub',c::text,true); result:=public.cast_restaurant_vote(r,3,'down');
  if (result->>'rating')::integer<>1 then raise exception 'silver did not fall to bronze'; end if;
  perform public.cast_restaurant_vote(r,4,'down');
  perform set_config('request.jwt.claim.sub',b::text,true); result:=public.cast_restaurant_vote(r,4,'down');
  if result->>'outcome'<>'deleted' then raise exception 'bronze did not delete'; end if;
  if exists(select 1 from public.restaurants where id=r) or exists(select 1 from public.restaurant_comments where restaurant_id=r) or exists(select 1 from public.restaurant_votes where restaurant_id=r) or exists(select 1 from public.restaurant_photos where restaurant_id=r) then raise exception 'associated records retained'; end if;
  if has_function_privilege('authenticated','public.claim_catalog_photo_cleanup(uuid,text)','EXECUTE') then raise exception 'private cleanup API exposed'; end if;
  perform set_config('role','postgres',true);
  if not exists(select 1 from private.restaurant_photo_cleanup where restaurant_id=r and r::text||'/test.jpg'=any(paths)) then raise exception 'file cleanup was not enqueued'; end if;
  if not exists(select 1 from public.restaurants where id=other_r) then raise exception 'other group record deleted'; end if;

  -- Verify paging, nickname scope and outsider access on the surviving record.
  insert into public.restaurant_comments(restaurant_id,user_id,body,created_at) select other_r,a,'의견 '||i,now()-i*interval '1 second' from generate_series(1,25)i;
  perform set_config('request.jwt.claim.sub',a::text,true); perform set_config('role','authenticated',true);
  state:=public.restaurant_discussion(other_r);
  if jsonb_array_length(state->'comments')<>21 or (state->>'comment_count')::integer<>25 then raise exception 'comment first page failed'; end if;
  result:=public.restaurant_discussion(other_r,(state->'comments'->19->>'created_at')::timestamptz,(state->'comments'->19->>'id')::uuid);
  if jsonb_array_length(result->'comments')<>5 then raise exception 'comment pagination failed'; end if;
  perform set_config('request.jwt.claim.sub',outsider::text,true);
  if exists(select 1 from public.restaurant_comments) then raise exception 'outsider read comments'; end if;
  begin perform public.restaurant_discussion(other_r); raise exception 'outsider read discussion'; exception when raise_exception then if sqlerrm<>'restaurant_unavailable' then raise; end if; end;
  begin perform public.cast_restaurant_vote(other_r,1,'down'); raise exception 'outsider voted'; exception when raise_exception then if sqlerrm<>'restaurant_unavailable' then raise; end if; end;
  perform set_config('role','postgres',true);
end $$;
select 'comments, registrant exclusion, strict majority, vote replacement, new rounds, gold limit, bronze deletion, private cleanup and other-group preservation passed' result;
rollback;
